mapper.select:
select * from wms_print
where
bool_delete_enum = 0

    and bool_printed = #{boolPrinted}


    and type = #{materialLabelPrintType}


    and project_ids is null


    and project_ids is not null


    and find_in_set(#{projectId},project_ids)


    
        and create_time >= #{createDate[0]}
    
    
        and create_time <= #{createDate[1]}
    


    and contain_basic_class & #{ basicClass} > 0

select wp.* from wms_print wp
left join wms_print_detail wpd on wpd.print_id = wp.id
where
wp.bool_delete_enum = 0

    and wpd.bool_party_a = #{boolPartyA}


    and wp.bool_printed = #{boolPrinted}


    and wp.type = #{materialLabelPrintType}


    and wp.project_ids is null


    and wp.project_ids is not null


    and find_in_set(#{projectId},wp.project_ids)


    
        and wp.create_time >= #{createDate[0]}
    
    
        and wp.create_time <= #{createDate[1]}
    


    and wp.contain_basic_class & #{ basicClass} > 0

GROUP BY wp.id

select wp.type , ifnull(sum(wpd.not_print_number),0) notPrinted from wms_print wp left join wms_print_detail wpd on wpd.print_id = wp.id where wpd.bool_printed = 0
and wpd.bool_party_a = #{boolPartyA}
GROUP BY wp.type
